CREATE TABLE IF NOT EXISTS gis_geometry_features (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_id UUID NOT NULL REFERENCES gis_geometry_sources(id), provider TEXT NOT NULL, feature_id TEXT NOT NULL, feature_name TEXT, state_code TEXT, parent_feature_id TEXT, geometry_wkt TEXT, geometry_geojson JSONB, normalized_geometry_available BOOLEAN NOT NULL DEFAULT false, geometry_valid BOOLEAN, geometry_empty BOOLEAN, source_srid TEXT, normalized_srid TEXT, validation_metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_id,feature_id));